// Research Watch — 19 Oct 2026.
//
// Field-wide literature and trial watch, as a sub-view of Publications rather than a seventh tab
// (the tab bar is already six items; a seventh shrinks every label on a phone).
//
// Content comes from watch.json, generated by a separate skill and pushed on its own. That is the
// source of the two things most worth testing:
//
//   1. It renders the real file, and an empty one, without throwing. The file is regenerated
//      outside this app by something that can change shape or go missing, and a view that breaks
//      on bad input takes the Publications view down with it — the view people actually came for.
//
//   2. Everything in it is escaped. The text is assembled from PubMed and ClinicalTrials.gov,
//      which nobody here controls, and it lands inside template literals.
const PROJECT = require("path").join(__dirname, "..");
const TESTDIR = __dirname;
const fs = require("fs");
const path = require("path");
const { JSDOM } = require("jsdom");
const { makeMockSupabase } = require(TESTDIR + "/supabase_mock.js");
const html = fs.readFileSync(PROJECT + "/research-tracker.html", "utf8");

// The real file as shipped. If it isn't beside the app the view must still work, so its absence
// is a scenario rather than a reason to skip.
const WATCH_PATH = path.join(PROJECT, "watch.json");
const realWatch = fs.existsSync(WATCH_PATH) ? JSON.parse(fs.readFileSync(WATCH_PATH, "utf8")) : null;

const USER = "test-user-1";
const now = new Date().toISOString();
const profile = () => ({
  id: USER, kind: "profile", updated_at: now, workspace: "sports-yanke",
  data: { id: USER, email: "a@example.com", name: "Adam Yanke", position: "Clinician",
    reportsTo: "", alertEmail: "", alertEmailAsked: true, degreesAsked: true,
    tourSeen: 1, fieldsChosen: true, linkedTo: "", admin: true },
});
const paper = (id, year) => ({
  id, kind: "study", updated_at: now, workspace: "sports-yanke",
  data: { id, title: "Paper " + id, phase: "Published", design: "Prospective (Consented)",
    priority: "Medium", pi: "Adam Yanke",
    publication: { pmid: "4" + id.slice(1).padStart(7, "0"), doi: "", year: String(year),
      title: "Paper " + id, journal: "Am J Sports Med",
      authors: [{ fore: "Adam", last: "Yanke", initials: "AB" }],
      authorList: "Adam Yanke", importedOn: "2026-10-12" } },
});

function boot() {
  const dom = new JSDOM(html, {
    runScripts: "dangerously", pretendToBeVisual: true, url: "http://localhost/",
    beforeParse(win) {
      win.matchMedia = () => ({ matches: false, addListener(){}, removeListener(){}, addEventListener(){}, removeEventListener(){} });
      win.confirm = () => true;
      win.localStorage.setItem("rt-seeded", "1");
      // No fetch in jsdom, so watch.json never arrives on its own — which is also the "file is
      // missing" case, tested below before anything is injected.
      win.supabase = { createClient: () => makeMockSupabase({
        items: [profile(), paper("p1", 2024), paper("p2", 2025), paper("p3", 2026)] }) };
    },
  });
  return dom.window;
}
const wait = ms => new Promise(r => setTimeout(r, ms));
let pass = 0, fail = 0;
function check(name, cond, detail) {
  if (cond) { console.log("  ok  ", name); pass++; }
  else { console.log("  FAIL", name, detail === undefined ? "" : "->" + JSON.stringify(detail)); fail++; }
}

(async () => {
  const w = boot();
  await wait(700);
  const ev = (c) => w.eval(c);

  console.log("\n-- It renders the real file without throwing --");
  check("watch.json is beside the app", !!realWatch, WATCH_PATH);
  w.__watch = realWatch;
  let out = "";
  let threw = null;
  try { out = ev("researchWatchHTML(window.__watch)"); } catch (e) { threw = String(e); }
  check("researchWatchHTML(real file) didn't throw", !threw, threw);
  check("...and produced markup", out.length > 500, out.length);
  check("...naming the trials section", /In development or early phase/.test(out));
  check("...and the papers section", /New papers that touch your publications/.test(out));
  realWatch.inDevelopment.forEach(d =>
    check("  trial " + d.id + " is listed", out.includes(d.id), d.id));
  realWatch.newPapers.forEach(p =>
    check("  paper PMID " + p.pmid + " is listed", out.includes(p.pmid), p.pmid));

  console.log("\n-- An empty object is a valid state, not a crash --");
  let emptyOut = "", emptyThrew = null;
  try { emptyOut = ev("researchWatchHTML({})"); } catch (e) { emptyThrew = String(e); }
  check("researchWatchHTML({}) didn't throw", !emptyThrew, emptyThrew);
  check("...and says there's nothing yet", /No Research Watch data yet/.test(emptyOut), emptyOut.slice(0, 200));
  // null and undefined reach this too: watchData starts null and stays null if the fetch fails.
  check("null doesn't throw either", /No Research Watch data yet/.test(ev("researchWatchHTML(null)")));
  check("undefined doesn't throw either", /No Research Watch data yet/.test(ev("researchWatchHTML(undefined)")));
  // Half a file — the generator could emit one section and not the other.
  check("a partial file renders what it has",
    /In development or early phase/.test(ev('researchWatchHTML({inDevelopment:[{id:"NCT1",kind:"k",meta:"m",title:"t",frame:"f",forWork:"w"}]})')));

  console.log("\n-- Everything from the file is escaped --");
  const nasty = {
    generated: "2026-10-19",
    inDevelopment: [{ id: '"><script>alert(1)</script>', kind: "<b>k</b>", meta: "m & m",
      title: "<img src=x onerror=alert(1)>", frame: "f", forWork: "w" }],
    newPapers: [{ pmid: "1'\"><svg onload=alert(1)>", doi: "javascript:alert(1)", verdict: "different",
      meta: "<i>meta</i>", title: "</h3><script>alert(1)</script>", frame: "f",
      versus: "v", forWork: "w", refs: [{ pmid: "2<script>", label: "L<script>" }] }],
    alsoNoted: [{ pmid: "3<script>", text: "<script>alert(1)</script>" }],
    meetingAbstracts: { note: "<script>alert(1)</script>", leadUrl: '" onmouseover="alert(1)' },
  };
  w.__nasty = nasty;
  const dirty = ev("researchWatchHTML(window.__nasty)");
  check("no raw <script> survives", !/<script/i.test(dirty), (dirty.match(/.{0,60}<script.{0,60}/i) || [])[0]);
  check("...and the dangerous text is present but escaped", /&lt;script&gt;/.test(dirty));
  // Rendering it into a real DOM is the honest check: if anything escaped, a node appears.
  // Matching raw text for "onerror=" is not — "&lt;img src=x onerror=alert(1)&gt;" contains that
  // substring and is completely inert, because the angle brackets are entities. Ask the parser.
  const probe = w.document.createElement("div");
  probe.innerHTML = dirty;
  const handlered = [...probe.querySelectorAll("*")].filter(el =>
    [...el.attributes].some(a => /^on/i.test(a.name)));
  check("no element carries an inline event handler", handlered.length === 0,
    handlered.map(el => el.outerHTML.slice(0, 80)));
  check("...and no javascript: URL is linkable",
    [...probe.querySelectorAll("a")].every(a => !/^javascript:/i.test(a.getAttribute("href") || "")),
    [...probe.querySelectorAll("a")].map(a => a.getAttribute("href")).filter(h => /^javascript:/i.test(h || "")));
  check("no script element materialises in the DOM", probe.querySelectorAll("script").length === 0);
  check("no img/svg element materialises either",
    probe.querySelectorAll("img, svg[onload]").length === 0);

  console.log("\n-- Outbound links are safe and open in a new tab --");
  const good = w.document.createElement("div");
  good.innerHTML = ev("researchWatchHTML(window.__watch)");
  const links = [...good.querySelectorAll("a")];
  check("there are links", links.length > 0, links.length);
  check("every one opens in a new tab", links.every(a => a.getAttribute("target") === "_blank"),
    links.filter(a => a.getAttribute("target") !== "_blank").map(a => a.outerHTML.slice(0, 80)));
  check("...with rel=noopener", links.every(a => /noopener/.test(a.getAttribute("rel") || "")),
    links.filter(a => !/noopener/.test(a.getAttribute("rel") || "")).map(a => a.outerHTML.slice(0, 80)));
  // Dark mode regression, found by looking at it: reference links live inside .rw-note, which the
  // original CSS didn't style, so they fell back to the browser's dark blue on a dark card.
  const rwCss = html.slice(html.indexOf("/* Research Watch */"), html.indexOf("/* Nested society subscriptions"));
  check("links inside a card are coloured, not left to the browser default",
    /\.rw-card a[^}]*\{[^}]*var\(--blue\)/.test(rwCss) || /\.rw-note a/.test(rwCss), rwCss.slice(0, 300));
  check("PubMed, DOI and ClinicalTrials are all linked",
    links.some(a => /pubmed\.ncbi/.test(a.href)) &&
    links.some(a => /doi\.org/.test(a.href)) &&
    links.some(a => /clinicaltrials\.gov/.test(a.href)));

  console.log("\n-- Colours come from variables, so dark mode works --");
  const css = html.slice(html.indexOf("/* Research Watch */"), html.indexOf("/* Research Watch */") + 1400);
  // One deliberate exception: #fff on the orange "Different" badge, which needs a fixed
  // foreground because --orange does not change between schemes.
  const hexes = (css.match(/#[0-9a-f]{3,8}\b/gi) || []).filter(h => h.toLowerCase() !== "#fff");
  check("no stray hex colours in the Research Watch CSS", hexes.length === 0, hexes);
  const chartSVG = ev("rwYearChartSVG([[2024,3],[2025,0],[2026,5]])");
  check("the chart uses --blue and --brand-teal",
    /var\(--blue\)/.test(chartSVG) && /var\(--brand-teal\)/.test(chartSVG));
  check("...and --line for the gridlines", /var\(--line\)/.test(chartSVG));
  check("...with no literal colours", !/#[0-9a-f]{3,8}\b/i.test(chartSVG) && !/rgba?\(/i.test(chartSVG));
  check("an empty series returns nothing", ev("rwYearChartSVG([])") === "");

  console.log("\n-- It's reachable from Publications, and Back works --");
  ev('tab = "studies"; showPublications = true; showWatch = false; render();');
  await wait(250);
  const btn = w.document.getElementById("pub-watch");
  check("Publications offers a Research Watch button", !!btn);
  w.__watch2 = realWatch;
  ev("watchData = window.__watch2");
  btn.click();
  await wait(250);
  check("it opens the view", ev("showWatch") === true);
  check("...showing the content", /In development or early phase/.test(w.document.querySelector("#main").textContent));
  check("...with its own Back control", !!w.document.getElementById("rw-back"));
  w.document.getElementById("rw-back").click();
  await wait(250);
  check("Back returns to Publications", ev("showWatch") === false
    && /Papers per year/.test(w.document.querySelector("#main").textContent));

  console.log("\n-- A missing file doesn't break Publications --");
  ev("watchData = null; showWatch = true; render();");
  await wait(250);
  check("the view says there's nothing yet",
    /No Research Watch data yet/.test(w.document.querySelector("#main").textContent));
  check("...and Back still works", !!w.document.getElementById("rw-back"));
  w.document.getElementById("rw-back").click();
  await wait(250);
  check("Publications is intact", /Papers per year/.test(w.document.querySelector("#main").textContent));

  console.log("\n-- Leaving the area clears the flag --");
  // Otherwise Back from a study later lands on a view the person never opened.
  ev("showWatch = true; tab = 'dashboard'; render();");
  await wait(150);
  const studiesTab = w.document.querySelector('button[data-tab="studies"]');
  studiesTab.click();
  await wait(250);
  check("the Studies tab shows studies, not a stale Research Watch", ev("showWatch") === false,
    ev("showWatch"));

  console.log("\n-- Nothing from watch.json reaches the database --");
  check("researchWatchHTML never writes", !/pushItem|from\("items"\)/.test(ev("String(researchWatchHTML)")));
  check("...nor does the renderer", !/pushItem|from\("items"\)/.test(ev("String(renderResearchWatch)")));

  console.log("\n" + pass + " passed, " + fail + " failed");
  process.exit(fail ? 1 : 0);
})().catch(e => { console.error("TEST FAILED:", e); process.exit(1); });
